<script setup lang="ts">
import { catalogApi } from '~/services/catalog.api'
import { moderatorApi } from '~/services/moderator.api'
import type { Category, Color, Size, Technique } from '~/types/catalog'
definePageMeta({ layout: 'moderator', middleware: 'moderator' })
const { data, refresh } = await useAsyncData<{ getCategories: Category[]; getTechniques: Technique[]; getSizes: Size[]; getColors: Color[] }>('catalog-options', catalogApi.metadata)
const colorName = ref(''); const colorHex = ref('#000000'); const sizeName = ref(''); const sizeOrder = ref(10); const message = ref(''); const error = ref('')
async function addColor() { try { await moderatorApi.upsertColor(colorName.value, colorHex.value); colorName.value = ''; message.value = 'Color saved.'; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to save color.' } }
async function addSize() { try { await moderatorApi.upsertSize(sizeName.value, sizeOrder.value); sizeName.value = ''; message.value = 'Size saved.'; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Unable to save size.' } }
</script>
<template><div><p class="text-xs font-bold uppercase tracking-widest text-slate-500">Catalogue control</p><h1 class="mt-2 font-display text-4xl">Colours, sizes & discounts</h1><p class="mt-3 max-w-2xl text-slate-600">Discounts are configured per product. Manage the reusable colour and size options below.</p><p v-if="error" class="mt-5 rounded-lg bg-rose-50 p-4 text-rose-800">{{ error }}</p><p v-if="message" class="mt-5 rounded-lg bg-emerald-50 p-4 text-emerald-800">{{ message }}</p><div class="mt-8 grid gap-6 lg:grid-cols-2"><section class="card p-6"><h2 class="font-display text-2xl">Colours</h2><form class="mt-5 flex gap-3" @submit.prevent="addColor"><input v-model="colorName" class="field" placeholder="Colour name" required><input v-model="colorHex" class="h-11 w-14 rounded border" type="color"><button class="button-primary">Save</button></form><ul class="mt-6 space-y-2"><li v-for="color in data?.getColors" :key="color.id" class="flex items-center gap-3"><span class="h-5 w-5 rounded-full border" :style="{ backgroundColor: color.hex }"/><span>{{ color.name }}</span></li></ul></section><section class="card p-6"><h2 class="font-display text-2xl">Sizes</h2><form class="mt-5 flex gap-3" @submit.prevent="addSize"><input v-model="sizeName" class="field" placeholder="Size name" required><input v-model.number="sizeOrder" class="field w-24" type="number" min="0"><button class="button-primary">Save</button></form><ul class="mt-6 flex flex-wrap gap-2"><li v-for="size in data?.getSizes" :key="size.id" class="rounded-full bg-slate-100 px-3 py-2 text-sm">{{ size.name }}</li></ul></section></div></div></template>
